--
-- Name: guard_account_profile_link_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_account_profile_link_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if coalesce(current_setting('app.learner_profile_link_mutation', true), '') = 'on'
    or pg_trigger_depth() > 1
  then
    return case when tg_op = 'DELETE' then old else new end;
  end if;

  if (tg_op = 'INSERT' and new.account_id is not null)
    or (tg_op = 'UPDATE' and new.account_id is distinct from old.account_id)
    or (tg_op = 'DELETE' and old.account_id is not null)
  then
    raise exception 'learner_profile_account_link_requires_supported_workflow'
      using errcode = '42501';
  end if;

  return case when tg_op = 'DELETE' then old else new end;
end
$$;


--
-- Name: guard_course_audience_type(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_course_audience_type() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_expected_type text;
begin
  v_expected_type := case
    when exists (
      select 1
      from public.course_learner as course_learner
      where course_learner.course_id = new.id
    ) or exists (
      select 1
      from public.course_learner_group as course_group
      where course_group.course_id = new.id
    ) then 'learner_profile'
    else 'none'
  end;

  if new.audience_type <> v_expected_type then
    raise exception
      'course_audience_type_is_derived'
      using errcode = '23514';
  end if;

  return new;
end
$$;


--
-- Name: guard_learner_identity_audit_append_only(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_learner_identity_audit_append_only() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if coalesce(current_setting('app.learner_identity_erasure', true), '') <> 'on' then
    raise exception 'learner_identity_audit_is_append_only' using errcode = '55000';
  end if;
  return case when tg_op = 'DELETE' then old else new end;
end
$$;


--
-- Name: guard_learner_profile_alias_immutable(); Type: FUNCTION; Schema: public; Owner: -
