--
-- Name: handle_auth_user_account(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_auth_user_account() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_account public.account%rowtype;
begin
  perform set_config('app.learner_profile_link_mutation', 'on', true);

  insert into public.account as target (
    auth_user_id,
    display_name,
    status
  )
  values (
    new.id,
    coalesce(
      nullif(btrim(new.raw_user_meta_data ->> 'full_name'), ''),
      nullif(btrim(new.raw_user_meta_data ->> 'name'), ''),
      nullif(split_part(coalesce(new.email, ''), '@', 1), ''),
      'Пользователь'
    ),
    case
      when new.raw_app_meta_data ->> 'identity_status' = 'provisional'
        then 'provisional'
      else 'active'
    end
  )
  on conflict (auth_user_id) do update
    set display_name = target.display_name
  returning target.* into v_account;

  insert into public.account_security (account_id)
  values (v_account.id)
  on conflict (account_id) do nothing;

  insert into public.account_preference (account_id)
  values (v_account.id)
  on conflict (account_id) do nothing;

  if not exists (
    select 1 from public.learner_profile as profile
    where profile.account_id = v_account.id
  ) then
    insert into public.learner_profile (display_name, account_id)
    values (v_account.display_name, v_account.id);
  end if;

  return new;
end
$$;


--
-- Name: invalidate_learner_ai_consent_on_course_group_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.invalidate_learner_ai_consent_on_course_group_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_profile_id uuid;
begin
  if tg_op = 'DELETE' then
    for v_profile_id in
      select member.learner_profile_id
      from public.learner_group_member as member
      where member.learner_group_id = old.learner_group_id
    loop
      perform public.invalidate_learner_ai_consent_scope(
        old.course_id, v_profile_id
      );
    end loop;
  elsif old.course_id is distinct from new.course_id
    or old.learner_group_id is distinct from new.learner_group_id
  then
    for v_profile_id in
      select member.learner_profile_id
      from public.learner_group_member as member
      where member.learner_group_id = old.learner_group_id
    loop
      perform public.invalidate_learner_ai_consent_scope(
        old.course_id, v_profile_id
      );
    end loop;
  end if;
  return case when tg_op = 'DELETE' then old else new end;
end
$$;


--
-- Name: invalidate_learner_ai_consent_on_course_owner_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.invalidate_learner_ai_consent_on_course_owner_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_profile_id uuid;
begin
  if new.owner_account_id is distinct from old.owner_account_id then
    for v_profile_id in
      select distinct consent.learner_profile_id
      from public.learner_ai_consent as consent
      where consent.course_id = new.id
        and consent.status in ('pending', 'active')
    loop
      perform public.invalidate_learner_ai_consent_scope(new.id, v_profile_id);
    end loop;
  end if;
  return new;
end
$$;


