--
-- Name: preview_my_learning_data_erasure(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.preview_my_learning_data_erasure() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_account_id uuid := public.current_account_id();
  v_profile_id uuid := public.current_owned_learner_profile_id();
  v_base jsonb;
  v_payload jsonb;
  v_fingerprint bytea;
begin
  if v_actor_account_id is null or v_profile_id is null then
    raise exception 'learner_profile_not_found' using errcode = 'P0002';
  end if;
  delete from public.learner_erasure_request
  where account_id = v_actor_account_id and consumed_at is null;
  v_base := public.learner_erasure_state_for_actor(
    v_actor_account_id, v_profile_id
  );
  v_fingerprint := extensions.digest(v_base::text, 'sha256');
  v_payload := (
    v_base - 'accountId' - 'currentLearnerProfileId' - 'scopeState'
  ) || jsonb_build_object(
    'previewFingerprint', encode(v_fingerprint, 'hex'),
    'generatedAt', now()
  );
  insert into public.learner_erasure_request (
    account_id, current_learner_profile_id, preview_fingerprint,
    preview_payload, expires_at
  ) values (
    v_actor_account_id, v_profile_id, v_fingerprint,
    v_payload, now() + interval '15 minutes'
  );
  perform public.append_learner_identity_audit(
    'learning_data_erasure_previewed', v_actor_account_id,
    v_actor_account_id, v_profile_id, null, null,
    jsonb_build_object('projectionVersion', 1)
  );
  return v_payload;
end
$$;


--
-- Name: preview_verified_email_learner_connection_request(uuid, uuid, bytea); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.preview_verified_email_learner_connection_request(p_actor_auth_user_id uuid, p_request_id uuid, p_recipient_email_digest bytea) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_account_id uuid := public.account_id_for_auth_user(p_actor_auth_user_id);
  v_request public.learner_connection_request%rowtype;
  v_was_unbound boolean;
begin
  if v_actor_account_id is null
    or p_recipient_email_digest is null
    or octet_length(p_recipient_email_digest) <> 32
  then
    raise exception 'learner_connection_request_not_found' using errcode = 'P0002';
  end if;
  select request.* into v_request
  from public.learner_connection_request as request
  where request.id = p_request_id
    and request.method = 'email'
    and request.recipient_email_digest = p_recipient_email_digest
    and (request.recipient_account_id is null
      or request.recipient_account_id = v_actor_account_id)
  for update of request;
  if not found then
    raise exception 'learner_connection_request_not_found' using errcode = 'P0002';
  end if;
  if v_request.status in ('accepted', 'rejected') then
    if v_request.recipient_account_id is distinct from v_actor_account_id then
      raise exception 'learner_connection_request_not_found' using errcode = 'P0002';
    end if;
  elsif v_request.status = 'pending' and v_request.expires_at > now() then
    v_was_unbound := v_request.recipient_account_id is null;
    update public.learner_connection_request as request
    set recipient_account_id = v_actor_account_id,
        updated_at = now()
    where request.id = v_request.id
      and (request.recipient_account_id is null
        or request.recipient_account_id = v_actor_account_id)
    returning request.* into v_request;
    if not found then
      raise exception 'learner_connection_request_not_found' using errcode = 'P0002';
    end if;
    if v_was_unbound then
      perform public.append_learner_identity_audit(
        'learner_connection_verified_email_bound', v_actor_account_id,
        v_actor_account_id, v_request.learner_profile_id,
        null, v_request.id,
        jsonb_build_object('method', 'email', 'projectionVersion', 1)
      );
    end if;
  else
    raise exception 'learner_connection_request_not_found' using errcode = 'P0002';
  end if;
  return public.preview_email_learner_connection_request(
    p_actor_auth_user_id, v_request.id,
    v_request.token_digest, p_recipient_email_digest
  );
end
$$;


--
-- Name: preview_verified_email_learner_observer_invitation(uuid, uuid, bytea); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.preview_verified_email_learner_observer_invitation(p_actor_auth_user_id uuid, p_invitation_id uuid, p_recipient_email_digest bytea) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_account_id uuid := public.account_id_for_auth_user(p_actor_auth_user_id);
  v_invitation public.learner_observer_invitation%rowtype;
  v_was_unbound boolean;
begin
  if v_actor_account_id is null
    or p_recipient_email_digest is null
    or octet_length(p_recipient_email_digest) <> 32
  then
    raise exception 'learner_observer_invitation_not_found' using errcode = 'P0002';
  end if;
  select invitation.* into v_invitation
  from public.learner_observer_invitation as invitation
  where invitation.id = p_invitation_id
    and invitation.recipient_email_digest = p_recipient_email_digest
    and invitation.subject_account_id <> v_actor_account_id
    and (invitation.recipient_account_id is null
      or invitation.recipient_account_id = v_actor_account_id)
  for update of invitation;
  if not found then
    raise exception 'learner_observer_invitation_not_found' using errcode = 'P0002';
  end if;
  if v_invitation.status in ('accepted', 'rejected') then
    if v_invitation.recipient_account_id is distinct from v_actor_account_id then
      raise exception 'learner_observer_invitation_not_found' using errcode = 'P0002';
    end if;
  elsif v_invitation.status in ('pending', 'bound')
    and v_invitation.expires_at > now()
  then
    v_was_unbound := v_invitation.recipient_account_id is null;
    update public.learner_observer_invitation as invitation
    set recipient_account_id = v_actor_account_id,
        status = 'bound',
        updated_at = now()
    where invitation.id = v_invitation.id
      and (invitation.recipient_account_id is null
        or invitation.recipient_account_id = v_actor_account_id)
    returning invitation.* into v_invitation;
    if not found then
      raise exception 'learner_observer_invitation_not_found' using errcode = 'P0002';
    end if;
    if v_was_unbound then
      perform public.append_learner_identity_audit(
        'learner_observer_invitation_verified_email_bound',
        v_actor_account_id, v_invitation.subject_account_id,
        v_invitation.learner_profile_id, null, v_invitation.id,
        jsonb_build_object('projectionVersion', 1)
      );
    end if;
  else
    raise exception 'learner_observer_invitation_not_found' using errcode = 'P0002';
  end if;
  return public.preview_email_learner_observer_invitation(
    p_actor_auth_user_id, v_invitation.id,
    v_invitation.token_digest, p_recipient_email_digest
  );
end
$$;


--
-- Name: preview_verified_learner_profile_invitation(uuid, uuid, bytea); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.preview_verified_learner_profile_invitation(p_actor_auth_user_id uuid, p_invitation_id uuid, p_recipient_email_digest bytea) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_account_id uuid := public.account_id_for_auth_user(p_actor_auth_user_id);
  v_invitation public.learner_claim_invitation%rowtype;
  v_was_unbound boolean;
begin
  if v_actor_account_id is null
    or p_recipient_email_digest is null
    or octet_length(p_recipient_email_digest) <> 32
  then
    raise exception 'learner_profile_invitation_not_found' using errcode = 'P0002';
  end if;

  select invitation.* into v_invitation
  from public.learner_claim_invitation as invitation
  where invitation.id = p_invitation_id
    and invitation.recipient_email_digest = p_recipient_email_digest
    and (invitation.recipient_account_id is null
      or invitation.recipient_account_id = v_actor_account_id)
  for update of invitation;
  if not found then
    raise exception 'learner_profile_invitation_not_found' using errcode = 'P0002';
  end if;

  if v_invitation.status in ('accepted', 'rejected') then
    if v_invitation.recipient_account_id is distinct from v_actor_account_id then
      raise exception 'learner_profile_invitation_not_found' using errcode = 'P0002';
    end if;
  elsif v_invitation.status in ('pending', 'bound')
    and v_invitation.expires_at > now()
  then
    v_was_unbound := v_invitation.recipient_account_id is null;
    update public.learner_claim_invitation as invitation
    set recipient_account_id = v_actor_account_id,
        status = 'bound',
        updated_at = now()
    where invitation.id = v_invitation.id
      and (invitation.recipient_account_id is null
        or invitation.recipient_account_id = v_actor_account_id)
    returning invitation.* into v_invitation;
    if not found then
      raise exception 'learner_profile_invitation_not_found' using errcode = 'P0002';
    end if;
    if v_was_unbound then
      perform public.append_learner_identity_audit(
        'learner_profile_invitation_verified_email_bound',
        v_actor_account_id, v_actor_account_id,
        v_invitation.source_learner_profile_id, null, v_invitation.id,
        jsonb_build_object('kind', v_invitation.kind, 'projectionVersion', 1)
      );
    end if;
  else
    raise exception 'learner_profile_invitation_not_found' using errcode = 'P0002';
  end if;

  return public.preview_learner_profile_invitation(
    p_actor_auth_user_id, v_invitation.id,
    v_invitation.token_digest, p_recipient_email_digest
  );
end
$$;


--
-- Name: reorder_lesson_component(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reorder_lesson_component(p_component_id uuid, p_new_position integer) RETURNS TABLE(id uuid, lesson_id uuid, type_key text, schema_version integer, "position" integer, payload jsonb, placement_config jsonb, visibility text, student_slide_id uuid, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_user_id uuid := (select auth.uid());
  v_lesson_id uuid;
  v_old_position integer;
  v_component_count integer;
  v_visibility text;
  v_student_slide_id uuid;
  v_current_slide_position integer;
  v_previous_slide_position integer;
  v_next_slide_position integer;
  v_clamped_slide_position integer;
  v_clamped_slide_id uuid;
begin
  if v_actor_user_id is null then
    raise exception 'component_not_found' using errcode = 'P0002';
  end if;

  if p_new_position is null or p_new_position < 1 then
    raise exception
      'component_position_out_of_range'
      using errcode = '22023';
  end if;

  select component.lesson_id
  into v_lesson_id
  from public.lesson_component as component
  join public.lesson as lesson on lesson.id = component.lesson_id
  join public.course as course on course.id = lesson.course_id
  join public.account as account on account.id = course.owner_account_id
  where component.id = p_component_id
    and account.auth_user_id = v_actor_user_id;

  if not found then
    raise exception 'component_not_found' using errcode = 'P0002';
  end if;

  perform 1
  from public.lesson as lesson
  join public.course as course on course.id = lesson.course_id
  join public.account as account on account.id = course.owner_account_id
  where lesson.id = v_lesson_id
    and account.auth_user_id = v_actor_user_id
  for update of lesson;

  if not found then
    raise exception 'component_not_found' using errcode = 'P0002';
  end if;

  perform 1
  from public.lesson_component as component
  where component.lesson_id = v_lesson_id
  order by component.id
  for update;

  perform 1
  from public.lesson_student_slide as slide
  where slide.lesson_id = v_lesson_id
  order by slide.id
  for update;

  select
    component.position,
    component.visibility,
    component.student_slide_id
  into v_old_position, v_visibility, v_student_slide_id
  from public.lesson_component as component
  where component.id = p_component_id
    and component.lesson_id = v_lesson_id;

  if not found then
    raise exception 'component_not_found' using errcode = 'P0002';
  end if;

  select count(*)::integer
  into v_component_count
  from public.lesson_component as component
  where component.lesson_id = v_lesson_id;

  if p_new_position > v_component_count then
    raise exception
      'component_position_out_of_range'
      using errcode = '22023';
  end if;

  if p_new_position < v_old_position then
    update public.lesson_component as component
    set position = component.position + 1
    where component.lesson_id = v_lesson_id
      and component.position >= p_new_position
      and component.position < v_old_position;
  elsif p_new_position > v_old_position then
    update public.lesson_component as component
    set position = component.position - 1
    where component.lesson_id = v_lesson_id
      and component.position > v_old_position
      and component.position <= p_new_position;
  end if;

  update public.lesson_component as component
  set position = p_new_position
  where component.id = p_component_id;

  if v_visibility = 'learner_visible' then
    select slide.position
    into v_current_slide_position
    from public.lesson_student_slide as slide
    where slide.id = v_student_slide_id
      and slide.lesson_id = v_lesson_id;

    select slide.position
    into v_previous_slide_position
    from public.lesson_component as component
    join public.lesson_student_slide as slide
      on slide.id = component.student_slide_id
    where component.lesson_id = v_lesson_id
      and component.id <> p_component_id
      and component.visibility = 'learner_visible'
      and component.position < p_new_position
    order by component.position desc
    limit 1;

    select slide.position
    into v_next_slide_position
    from public.lesson_component as component
    join public.lesson_student_slide as slide
      on slide.id = component.student_slide_id
    where component.lesson_id = v_lesson_id
      and component.id <> p_component_id
      and component.visibility = 'learner_visible'
      and component.position > p_new_position
    order by component.position
    limit 1;

    v_clamped_slide_position := v_current_slide_position;

    if v_previous_slide_position is not null
      and v_clamped_slide_position < v_previous_slide_position
    then
      v_clamped_slide_position := v_previous_slide_position;
    end if;

    if v_next_slide_position is not null
      and v_clamped_slide_position > v_next_slide_position
    then
      v_clamped_slide_position := v_next_slide_position;
    end if;

    if v_clamped_slide_position <> v_current_slide_position then
      select slide.id
      into v_clamped_slide_id
      from public.lesson_student_slide as slide
      where slide.lesson_id = v_lesson_id
        and slide.position = v_clamped_slide_position;

      update public.lesson_component as component
      set student_slide_id = v_clamped_slide_id
      where component.id = p_component_id;
    end if;
  end if;

  return query
  select
    component.id,
    component.lesson_id,
    component.type_key,
    component.schema_version,
    component.position,
    component.payload,
    component.placement_config,
    component.visibility,
    component.student_slide_id,
    component.created_at,
    component.updated_at
  from public.lesson_component as component
  where component.id = p_component_id
    and component.lesson_id = v_lesson_id;
end
$$;


--
-- Name: replace_course_audience(uuid, uuid[], uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.replace_course_audience(p_course_id uuid, p_direct_learner_profile_ids uuid[] DEFAULT '{}'::uuid[], p_learner_group_ids uuid[] DEFAULT '{}'::uuid[]) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_user_id uuid := (select auth.uid());
  v_teacher_account_id uuid;
  v_direct_ids uuid[];
  v_group_ids uuid[];
  v_effective_count integer;
begin
  if v_actor_user_id is null then
    raise exception 'course_not_found' using errcode = 'P0002';
  end if;

  if array_position(p_direct_learner_profile_ids, null) is not null
    or array_position(p_learner_group_ids, null) is not null
    or cardinality(coalesce(p_direct_learner_profile_ids, '{}'::uuid[])) > 200
    or cardinality(coalesce(p_learner_group_ids, '{}'::uuid[])) > 200
  then
    raise exception 'course_audience_ids_invalid' using errcode = '22023';
  end if;

  select account.id
  into v_teacher_account_id
  from public.account as account
  where account.auth_user_id = v_actor_user_id
  for update of account;

  if not found then
    raise exception 'course_not_found' using errcode = 'P0002';
  end if;

  perform 1
  from public.course as course
  where course.id = p_course_id
    and course.owner_account_id = v_teacher_account_id
  for update of course;

  if not found then
    raise exception 'course_not_found' using errcode = 'P0002';
  end if;

  select coalesce(array_agg(requested.id order by requested.id), '{}'::uuid[])
  into v_direct_ids
  from (
    select distinct requested_id as id
    from unnest(coalesce(p_direct_learner_profile_ids, '{}'::uuid[]))
      as requested(requested_id)
  ) as requested;

  select coalesce(array_agg(requested.id order by requested.id), '{}'::uuid[])
  into v_group_ids
  from (
    select distinct requested_id as id
    from unnest(coalesce(p_learner_group_ids, '{}'::uuid[]))
      as requested(requested_id)
  ) as requested;

  perform 1
  from public.learner_group as learner_group
  where learner_group.id = any(v_group_ids)
    and learner_group.owner_account_id = v_teacher_account_id
  order by learner_group.id
  for update of learner_group;

  if cardinality(v_group_ids) <> (
    select count(*)
    from public.learner_group as learner_group
    where learner_group.id = any(v_group_ids)
      and learner_group.owner_account_id = v_teacher_account_id
  ) then
    raise exception 'learner_group_not_found' using errcode = 'P0002';
  end if;

  perform 1
  from public.teacher_learner as teacher_learner
  where teacher_learner.teacher_account_id = v_teacher_account_id
    and teacher_learner.learner_profile_id = any(v_direct_ids)
    and teacher_learner.archived_at is null
  order by teacher_learner.learner_profile_id
  for update of teacher_learner;

  if cardinality(v_direct_ids) <> (
    select count(*)
    from public.teacher_learner as teacher_learner
    where teacher_learner.teacher_account_id = v_teacher_account_id
      and teacher_learner.learner_profile_id = any(v_direct_ids)
      and teacher_learner.archived_at is null
  ) then
    raise exception 'learner_profile_not_found' using errcode = 'P0002';
  end if;

  select count(*)
  into v_effective_count
  from (
    select requested.id
    from unnest(v_direct_ids) as requested(id)
    union
    select member.learner_profile_id
    from public.learner_group_member as member
    join public.teacher_learner as teacher_learner
      on teacher_learner.teacher_account_id = v_teacher_account_id
     and teacher_learner.learner_profile_id = member.learner_profile_id
     and teacher_learner.archived_at is null
    where member.learner_group_id = any(v_group_ids)
  ) as effective;

  if v_effective_count > 200 then
    raise exception 'course_audience_too_large' using errcode = '22023';
  end if;

  delete from public.course_learner as course_learner
  where course_learner.course_id = p_course_id
    and not (course_learner.learner_profile_id = any(v_direct_ids));

  insert into public.course_learner (course_id, learner_profile_id)
  select p_course_id, requested.id
  from unnest(v_direct_ids) as requested(id)
  on conflict (course_id, learner_profile_id) do nothing;

  delete from public.course_learner_group as course_group
  where course_group.course_id = p_course_id
    and not (course_group.learner_group_id = any(v_group_ids));

  insert into public.course_learner_group (course_id, learner_group_id)
  select p_course_id, requested.id
  from unnest(v_group_ids) as requested(id)
  on conflict (course_id, learner_group_id) do nothing;

  return true;
end
$$;


--
-- Name: replace_course_learners(uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.replace_course_learners(p_course_id uuid, p_learner_profile_ids uuid[]) RETURNS SETOF public.teacher_learner
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_group_ids uuid[];
  v_teacher_account_id uuid;
begin
  select course.owner_account_id
  into v_teacher_account_id
  from public.course as course
  where course.id = p_course_id;

  select coalesce(
    array_agg(course_group.learner_group_id order by course_group.learner_group_id),
    '{}'::uuid[]
  )
  into v_group_ids
  from public.course_learner_group as course_group
  where course_group.course_id = p_course_id;

  perform public.replace_course_audience(
    p_course_id,
    coalesce(p_learner_profile_ids, '{}'::uuid[]),
    v_group_ids
  );

  return query
  select teacher_learner.*
  from public.teacher_learner as teacher_learner
  join public.course_learner as course_learner
    on course_learner.learner_profile_id = teacher_learner.learner_profile_id
  where course_learner.course_id = p_course_id
    and teacher_learner.teacher_account_id = v_teacher_account_id
    and teacher_learner.archived_at is null
  order by teacher_learner.display_name, teacher_learner.learner_profile_id;
end
$$;


--
-- Name: request_learner_ai_consent(uuid, uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_learner_ai_consent(p_course_id uuid, p_learner_profile_id uuid, p_purpose text, p_expires_in_days integer DEFAULT 90) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_account_id uuid := public.current_account_id();
  v_subject_account_id uuid;
  v_consent public.learner_ai_consent%rowtype;
begin
  if p_purpose is null or btrim(p_purpose) = ''
    or char_length(btrim(p_purpose)) > 400
    or p_expires_in_days not between 1 and 365
  then
    raise exception 'learner_ai_consent_request_invalid' using errcode = '22023';
  end if;
  if not exists (
    select 1 from public.course as course
    where course.id = p_course_id and course.owner_account_id = v_actor_account_id
  ) or not public.course_has_effective_learner(p_course_id, p_learner_profile_id)
  then
    raise exception 'learner_ai_consent_scope_not_found' using errcode = 'P0002';
  end if;
  select profile.account_id into v_subject_account_id
  from public.learner_profile as profile
  where profile.id = p_learner_profile_id;
  if v_subject_account_id is null then
    raise exception 'learner_ai_consent_subject_unclaimed' using errcode = '55000';
  end if;
  insert into public.learner_ai_consent as target (
    learner_profile_id, course_id, owner_account_id, purpose,
    status, revision, expires_at
  ) values (
    p_learner_profile_id, p_course_id, v_actor_account_id, btrim(p_purpose),
    'pending', 1, now() + make_interval(days => p_expires_in_days)
  ) on conflict (learner_profile_id, course_id, owner_account_id) do update
    set purpose = excluded.purpose,
        status = 'pending',
        revision = target.revision + 1,
        expires_at = excluded.expires_at,
        granted_at = null,
        revoked_at = null
  returning * into v_consent;
  perform public.append_learner_identity_audit(
    'learner_ai_consent_requested', v_actor_account_id,
    v_subject_account_id, p_learner_profile_id, null, v_consent.id,
    jsonb_build_object('revision', v_consent.revision, 'projectionVersion', 1)
  );
  return jsonb_build_object(
    'id', v_consent.id,
    'learnerProfileId', v_consent.learner_profile_id,
    'courseId', v_consent.course_id,
    'courseTitle', (select title from public.course where id = v_consent.course_id),
    'ownerLabel', (select display_name from public.account where id = v_consent.owner_account_id),
    'purpose', v_consent.purpose,
    'status', v_consent.status,
    'revision', v_consent.revision,
    'expiresAt', v_consent.expires_at,
    'createdAt', v_consent.created_at,
    'grantedAt', v_consent.granted_at,
    'revokedAt', v_consent.revoked_at
  );
end
$$;


--
-- Name: reset_recoverable_learner_credentials(uuid, uuid, text, text, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reset_recoverable_learner_credentials(p_actor_auth_user_id uuid, p_grant_id uuid, p_new_child_login text, p_raw_pin text, p_reauthenticated_at timestamp with time zone, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  return public.reset_recoverable_learner_credentials_impl(
    p_actor_auth_user_id, p_grant_id,
    p_new_child_login, p_raw_pin,
    p_reauthenticated_at, p_idempotency_key
  );
end
$$;


--
-- Name: reset_recoverable_learner_credentials_impl(uuid, uuid, text, text, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reset_recoverable_learner_credentials_impl(p_actor_auth_user_id uuid, p_grant_id uuid, p_new_child_login text, p_raw_pin text, p_reauthenticated_at timestamp with time zone, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_actor_account_id uuid := public.account_id_for_auth_user(p_actor_auth_user_id);
  v_delegate public.learner_credential_recovery_delegate%rowtype;
  v_subject public.account%rowtype;
  v_profile_id uuid;
  v_pin_hash text;
  v_cutoff timestamptz := clock_timestamp();
  v_result jsonb;
begin
  if v_actor_account_id is null
    or p_grant_id is null
    or p_idempotency_key is null
    or p_new_child_login is null
    or lower(btrim(p_new_child_login)) !~ '^[[:alnum:]_.-]{3,80}$'
    or p_raw_pin is null or p_raw_pin !~ '^\d{4,8}$'
    or p_reauthenticated_at is null
    or p_reauthenticated_at < clock_timestamp() - interval '5 minutes'
    or p_reauthenticated_at > clock_timestamp() + interval '1 minute'
  then
    raise exception 'learner_credential_recovery_not_found' using errcode = 'P0002';
  end if;

  select delegate.* into v_delegate
  from public.learner_credential_recovery_delegate as delegate
  where delegate.id = p_grant_id
    and delegate.delegate_account_id = v_actor_account_id
    and delegate.status = 'active'
  for update of delegate;
  if not found then
    raise exception 'learner_credential_recovery_not_found' using errcode = 'P0002';
  end if;

  if v_delegate.last_reset_idempotency_key = p_idempotency_key
    and v_delegate.last_reset_result is not null
  then
    return v_delegate.last_reset_result;
  end if;

  if not public.learner_identity_rate_limit_hit(
    'credential_recovery_reset',
    extensions.digest(
      v_actor_account_id::text || ':' || p_grant_id::text,
      'sha256'
    ),
    5, interval '1 hour', interval '1 hour'
  ) then
    raise exception 'learner_identity_rate_limited' using errcode = 'P0001';
  end if;

  select account.* into v_subject
  from public.account as account
  where account.id = v_delegate.subject_account_id
    and account.status = 'active'
  for update of account;
  if not found then
    raise exception 'learner_credential_recovery_not_found' using errcode = 'P0002';
  end if;
  select profile.id into v_profile_id
  from public.learner_profile as profile
  where profile.account_id = v_subject.id
  for update of profile;
  if not found then
    raise exception 'learner_credential_recovery_not_found' using errcode = 'P0002';
  end if;

  update public.account_login_alias as alias
  set normalized_login = lower(btrim(p_new_child_login)),
      revoked_at = null,
      updated_at = now()
  where alias.account_id = v_subject.id
    and alias.kind = 'login';
  if not found then
    insert into public.account_login_alias (
      account_id, normalized_login, kind
    ) values (
      v_subject.id, lower(btrim(p_new_child_login)), 'login'
    );
  end if;

  v_pin_hash := extensions.crypt(p_raw_pin, extensions.gen_salt('bf'));
  insert into public.account_security as security (
    account_id, pin_hash, pin_failed_attempts, pin_created_at,
    pin_updated_at, sessions_invalid_before
  ) values (
    v_subject.id, v_pin_hash, 0, now(), now(), v_cutoff
  ) on conflict (account_id) do update
    set pin_hash = excluded.pin_hash,
        pin_failed_attempts = 0,
        pin_locked_until = null,
        pin_created_at = coalesce(security.pin_created_at, now()),
        pin_updated_at = now(),
        sessions_invalid_before = greatest(
          coalesce(security.sessions_invalid_before, '-infinity'::timestamptz),
          v_cutoff
        );

  v_result := jsonb_build_object(
    'grantId', v_delegate.id,
    'learnerLabel', v_subject.display_name,
    'childAccountLogin', lower(btrim(p_new_child_login)),
    'completed', true
  );
  update public.learner_credential_recovery_delegate
  set last_reset_idempotency_key = p_idempotency_key,
      last_reset_result = v_result,
      updated_at = now()
  where id = v_delegate.id;
  perform public.append_learner_identity_audit(
    'learner_credentials_recovered', v_actor_account_id,
    v_subject.id, v_profile_id, null, v_delegate.id,
    jsonb_build_object('projectionVersion', 1)
  );
  return v_result;
exception
  when unique_violation then
    raise exception 'learner_recovery_login_unavailable' using errcode = '23505';
end
$_$;


--
-- Name: resolve_account_login_alias(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_account_login_alias(p_identifier text) RETURNS TABLE(auth_user_id uuid, auth_email text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select account.auth_user_id, auth_user.email::text
  from public.account_login_alias as alias
  join public.account as account on account.id = alias.account_id
  join auth.users as auth_user on auth_user.id = account.auth_user_id
  where alias.normalized_login = lower(btrim(p_identifier))
    and alias.revoked_at is null
    and account.status = 'active'
  limit 1;
$$;


--
-- Name: resolve_learner_profile_alias(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_learner_profile_alias(p_learner_profile_id uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(
    (
      select alias.target_learner_profile_id
      from public.learner_profile_alias as alias
      where alias.source_learner_profile_id = p_learner_profile_id
    ),
    (
      select profile.id
      from public.learner_profile as profile
      where profile.id = p_learner_profile_id
    )
  );
$$;


--
-- Name: resolve_teacher_learner_profile_alias(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_teacher_learner_profile_alias(p_actor_auth_user_id uuid, p_learner_profile_id uuid) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_account_id uuid := public.account_id_for_auth_user(p_actor_auth_user_id);
  v_target_id uuid := public.resolve_learner_profile_alias(p_learner_profile_id);
begin
  if v_target_id is null or not exists (
    select 1 from public.teacher_learner as relation
    where relation.teacher_account_id = v_actor_account_id
      and relation.learner_profile_id = v_target_id
  ) then
    raise exception 'learner_profile_not_found' using errcode = 'P0002';
  end if;
  return v_target_id;
end
$$;


--
-- Name: restore_teacher_learner(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.restore_teacher_learner(p_learner_profile_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_account_id uuid := public.current_account_id();
  v_relation public.teacher_learner%rowtype;
  v_profile public.learner_profile%rowtype;
begin
  update public.teacher_learner as relation
  set archived_at = null
  where relation.teacher_account_id = v_actor_account_id
    and relation.learner_profile_id = public.resolve_learner_profile_alias(p_learner_profile_id)
    and relation.archived_at is not null
  returning relation.* into v_relation;
  if not found then
    raise exception 'learner_profile_not_found' using errcode = 'P0002';
  end if;
  select * into v_profile from public.learner_profile where id = v_relation.learner_profile_id;
  perform public.append_learner_identity_audit(
    'teacher_learner_restored', v_actor_account_id, v_profile.account_id,
    v_profile.id, null, null, '{}'::jsonb
  );
  return jsonb_build_object(
    'learnerProfileId', v_relation.learner_profile_id,
    'teacherAccountId', v_relation.teacher_account_id,
    'displayName', v_relation.display_name,
    'archivedAt', v_relation.archived_at,
    'identityState', case
      when v_profile.account_id is null then 'offline'
      when exists (
        select 1 from public.learner_profile_alias as alias
        where alias.target_learner_profile_id = v_profile.id
      ) then 'merged'
      else 'claimed'
    end,
    'pendingRequestCount', 0,
    'canInvite', v_profile.account_id is null,
    'canPermanentlyDelete', false,
    'createdAt', v_relation.created_at,
    'updatedAt', v_relation.updated_at
  );
end
$$;


--
-- Name: revoke_learner_profile_invitation(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revoke_learner_profile_invitation(p_invitation_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_account_id uuid := public.current_account_id();
  v_invitation public.learner_claim_invitation%rowtype;
begin
  if not public.learner_identity_rate_limit_hit(
    'profile_invitation_revoke',
    extensions.digest(
      coalesce(v_actor_account_id::text, '') || ':' || p_invitation_id::text,
      'sha256'
    ),
    30, interval '1 hour', interval '1 hour'
  ) then
    raise exception 'learner_identity_rate_limited' using errcode = 'P0001';
  end if;
  update public.learner_claim_invitation as invitation
  set status = 'revoked', revoked_at = now(), token_digest = token_digest
  where invitation.id = p_invitation_id
    and invitation.inviter_account_id = v_actor_account_id
    and invitation.status in ('pending', 'bound')
  returning invitation.* into v_invitation;
  if not found then
    raise exception 'learner_profile_invitation_not_found' using errcode = 'P0002';
  end if;
  update public.learner_profile_merge
  set status = 'cancelled', cancelled_at = now()
  where invitation_id = v_invitation.id and status in ('pending', 'ready');
  perform public.append_learner_identity_audit(
    'learner_profile_invitation_revoked', v_actor_account_id,
    v_invitation.recipient_account_id, v_invitation.source_learner_profile_id,
    null, v_invitation.id,
    jsonb_build_object('kind', v_invitation.kind, 'projectionVersion', 1)
  );
  return jsonb_build_object(
    'id', v_invitation.id, 'kind', v_invitation.kind,
    'status', v_invitation.status,
    'learnerProfileId', v_invitation.source_learner_profile_id,
    'learnerLabel', coalesce((select display_name from public.learner_profile where id = v_invitation.source_learner_profile_id), 'Учебный профиль'),
    'inviterLabel', (select display_name from public.account where id = v_actor_account_id),
    'expiresAt', v_invitation.expires_at, 'createdAt', v_invitation.created_at,
    'acceptedAt', v_invitation.accepted_at
  );
end
$$;


--
-- Name: revoke_my_learner_credential_recovery_delegate(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revoke_my_learner_credential_recovery_delegate(p_grant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_account_id uuid := public.current_account_id();
  v_delegate public.learner_credential_recovery_delegate%rowtype;
begin
  select delegate.* into v_delegate
  from public.learner_credential_recovery_delegate as delegate
  where delegate.id = p_grant_id
    and delegate.subject_account_id = v_actor_account_id
  for update of delegate;
  if not found then
    raise exception 'learner_credential_recovery_not_found' using errcode = 'P0002';
  end if;
  if v_delegate.status = 'active' then
    update public.learner_credential_recovery_delegate as delegate
    set status = 'revoked', revoked_at = now(), updated_at = now()
    where delegate.id = v_delegate.id
    returning delegate.* into v_delegate;
    perform public.append_learner_identity_audit(
      'learner_credential_recovery_delegate_revoked',
      v_actor_account_id, v_actor_account_id,
      public.current_owned_learner_profile_id(), null, v_delegate.id,
      jsonb_build_object('projectionVersion', 1)
    );
  end if;
  return jsonb_build_object(
    'grantId', v_delegate.id,
    'status', v_delegate.status,
    'revokedAt', v_delegate.revoked_at
  );
end
$$;


--
-- Name: revoke_user_sessions(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revoke_user_sessions(p_user_id uuid, p_cutoff timestamp with time zone DEFAULT now()) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  return public.revoke_user_sessions_impl(p_user_id, p_cutoff);
end
$$;


--
-- Name: revoke_user_sessions_impl(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revoke_user_sessions_impl(p_user_id uuid, p_cutoff timestamp with time zone) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_cutoff timestamptz;
begin
  if p_user_id is null or p_cutoff is null then
    raise exception 'session_revocation_invalid' using errcode = '22023';
  end if;

  update public.account_security as security
  set sessions_invalid_before = greatest(
        coalesce(security.sessions_invalid_before, '-infinity'::timestamptz),
        p_cutoff
      )
  from public.account as account
  where account.id = security.account_id
    and account.auth_user_id = p_user_id
  returning security.sessions_invalid_before into v_cutoff;

  return v_cutoff;
end
$$;


--
-- Name: rotate_my_learner_share_code(uuid, bytea, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rotate_my_learner_share_code(p_actor_auth_user_id uuid, p_code_digest bytea, p_expires_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_account_id uuid := public.account_id_for_auth_user(p_actor_auth_user_id);
  v_profile_id uuid;
  v_row public.learner_profile_share_code%rowtype;
  v_expired_code public.learner_profile_share_code%rowtype;
begin
  if v_actor_account_id is null
    or p_code_digest is null or octet_length(p_code_digest) <> 32
    or p_expires_at <= now() or p_expires_at > now() + interval '30 days'
  then
    raise exception 'learner_share_code_invalid' using errcode = '22023';
  end if;
  select profile.id into v_profile_id
  from public.learner_profile as profile
  where profile.account_id = v_actor_account_id
  for update of profile;
  if not found then
    raise exception 'learner_profile_not_found' using errcode = 'P0002';
  end if;

  for v_expired_code in
    update public.learner_profile_share_code as code
    set status = 'expired'
    where code.learner_profile_id = v_profile_id
      and code.status = 'active' and code.expires_at <= now()
    returning code.*
  loop
    perform public.append_learner_identity_audit(
      'learner_share_code_expired', v_actor_account_id, v_actor_account_id,
      v_profile_id, null, v_expired_code.id,
      jsonb_build_object(
        'expiredAt', v_expired_code.expires_at,
        'projectionVersion', 1
      )
    );
  end loop;
  update public.learner_profile_share_code
  set status = 'revoked', revoked_at = now()
  where learner_profile_id = v_profile_id and status = 'active';
  insert into public.learner_profile_share_code (
    learner_profile_id, code_digest, expires_at
  ) values (v_profile_id, p_code_digest, p_expires_at)
  returning * into v_row;
  perform public.append_learner_identity_audit(
    'learner_share_code_rotated', v_actor_account_id, v_actor_account_id,
    v_profile_id, null, v_row.id,
    jsonb_build_object('expiresAt', p_expires_at, 'projectionVersion', 1)
  );
  return jsonb_build_object(
    'expiresAt', v_row.expires_at,
    'createdAt', v_row.created_at
  );
end
$$;


--
-- Name: schedule_lesson_run(uuid, timestamp with time zone, integer, uuid[], uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.schedule_lesson_run(p_lesson_id uuid, p_scheduled_at timestamp with time zone, p_planned_duration_minutes integer DEFAULT NULL::integer, p_learner_profile_ids uuid[] DEFAULT NULL::uuid[], p_expected_lesson_run_id uuid DEFAULT NULL::uuid) RETURNS public.lesson_run
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_user_id uuid := (select auth.uid());
  v_teacher_account_id uuid;
  v_course_id uuid;
  v_duration_minutes integer;
  v_selected_ids uuid[];
  v_run public.lesson_run%rowtype;
begin
  if v_actor_user_id is null then
    raise exception 'lesson_not_found' using errcode = 'P0002';
  end if;

  if p_scheduled_at is null then
    raise exception
      'lesson_run_scheduled_at_required'
      using errcode = '22023';
  end if;

  if p_planned_duration_minutes is not null
    and p_planned_duration_minutes not between 5 and 480
  then
    raise exception
      'lesson_run_duration_invalid'
      using errcode = '22023';
  end if;

  if p_learner_profile_ids is not null
    and array_position(p_learner_profile_ids, null) is not null
  then
    raise exception
      'learner_profile_ids_must_not_contain_null'
      using errcode = '22023';
  end if;

  if cardinality(coalesce(p_learner_profile_ids, '{}'::uuid[])) > 200 then
    raise exception
      'lesson_run_audience_too_large'
      using errcode = '22023';
  end if;

  select course.owner_account_id, course.id
  into v_teacher_account_id, v_course_id
  from public.lesson as lesson
  join public.course as course on course.id = lesson.course_id
  join public.account as account on account.id = course.owner_account_id
  where lesson.id = p_lesson_id
    and account.auth_user_id = v_actor_user_id;

  if not found then
    raise exception 'lesson_not_found' using errcode = 'P0002';
  end if;

  perform 1
  from public.account as account
  where account.id = v_teacher_account_id
    and account.auth_user_id = v_actor_user_id
  for update of account;

  if not found then
    raise exception 'lesson_not_found' using errcode = 'P0002';
  end if;

  perform 1
  from public.course as course
  where course.id = v_course_id
    and course.owner_account_id = v_teacher_account_id
  for update of course;

  if not found then
    raise exception 'lesson_not_found' using errcode = 'P0002';
  end if;

  select coalesce(
    p_planned_duration_minutes,
    case
      when lesson.estimated_duration_minutes between 5 and 480
        then lesson.estimated_duration_minutes
      else null
    end,
    60
  )
  into v_duration_minutes
  from public.lesson as lesson
  where lesson.id = p_lesson_id
    and lesson.course_id = v_course_id
  for update of lesson;

  if not found then
    raise exception 'lesson_not_found' using errcode = 'P0002';
  end if;

  select run.*
  into v_run
  from public.lesson_run as run
  where run.lesson_id = p_lesson_id
    and run.ended_at is null
    and run.cancelled_at is null
  for update of run;

  if p_expected_lesson_run_id is not null
    and (
      v_run.id is null
      or v_run.id <> p_expected_lesson_run_id
    )
  then
    raise exception
      'lesson_run_changed'
      using errcode = '55000';
  end if;

  if v_run.id is not null and v_run.started_at is not null then
    raise exception
      'lesson_run_already_started'
      using errcode = '55000';
  end if;

  if v_run.id is not null then
    perform 1
    from public.learning_record as record
    where record.lesson_run_id = v_run.id
    order by record.id
    for update of record;

    if exists (
      select 1
      from public.learning_record as record
      where record.lesson_run_id = v_run.id
        and record.occurred_at is not null
    ) then
      raise exception
        'lesson_run_contains_finalized_records'
        using errcode = '55000';
    end if;
  end if;

  if p_learner_profile_ids is null and v_run.id is not null then
    select coalesce(
      array_agg(record.learner_profile_id order by record.learner_profile_id),
      '{}'::uuid[]
    )
    into v_selected_ids
    from public.learning_record as record
    where record.lesson_run_id = v_run.id
      and record.occurred_at is null;
  elsif p_learner_profile_ids is null then
    select coalesce(array_agg(effective.id order by effective.id), '{}'::uuid[])
    into v_selected_ids
    from (
      select course_learner.learner_profile_id as id
      from public.course_learner as course_learner
      join public.teacher_learner as teacher_learner
        on teacher_learner.teacher_account_id = v_teacher_account_id
       and teacher_learner.learner_profile_id = course_learner.learner_profile_id
       and teacher_learner.archived_at is null
      where course_learner.course_id = v_course_id
      union
      select member.learner_profile_id as id
      from public.course_learner_group as course_group
      join public.learner_group_member as member
        on member.learner_group_id = course_group.learner_group_id
      join public.teacher_learner as teacher_learner
        on teacher_learner.teacher_account_id = v_teacher_account_id
       and teacher_learner.learner_profile_id = member.learner_profile_id
       and teacher_learner.archived_at is null
      where course_group.course_id = v_course_id
    ) as effective;
  else
    select coalesce(array_agg(requested.id order by requested.id), '{}'::uuid[])
    into v_selected_ids
    from (
      select distinct requested_id as id
      from unnest(p_learner_profile_ids) as requested(requested_id)
    ) as requested;

    if exists (
      select 1
      from unnest(v_selected_ids) as requested(id)
      left join (
        select course_learner.learner_profile_id as id
        from public.course_learner as course_learner
        join public.teacher_learner as teacher_learner
          on teacher_learner.teacher_account_id = v_teacher_account_id
         and teacher_learner.learner_profile_id = course_learner.learner_profile_id
         and teacher_learner.archived_at is null
        where course_learner.course_id = v_course_id
        union
        select member.learner_profile_id as id
        from public.course_learner_group as course_group
        join public.learner_group_member as member
          on member.learner_group_id = course_group.learner_group_id
        join public.teacher_learner as teacher_learner
          on teacher_learner.teacher_account_id = v_teacher_account_id
         and teacher_learner.learner_profile_id = member.learner_profile_id
         and teacher_learner.archived_at is null
        where course_group.course_id = v_course_id
        union
        select record.learner_profile_id as id
        from public.learning_record as record
        where v_run.id is not null
          and record.lesson_run_id = v_run.id
          and record.occurred_at is null
          and record.recorded_by_account_id = v_teacher_account_id
      ) as allowed on allowed.id = requested.id
      where allowed.id is null
    ) then
      raise exception
        'learner_profile_not_in_course'
        using errcode = 'P0002';
    end if;
  end if;

  if cardinality(v_selected_ids) = 0 then
    raise exception
      'lesson_run_requires_expected_learner'
      using errcode = '23514';
  end if;

  if cardinality(v_selected_ids) > 200 then
    raise exception
      'lesson_run_audience_too_large'
      using errcode = '22023';
  end if;

  perform 1
  from public.teacher_learner as teacher_learner
  where teacher_learner.teacher_account_id = v_teacher_account_id
    and teacher_learner.learner_profile_id = any(v_selected_ids)
  order by teacher_learner.learner_profile_id
  for key share of teacher_learner;

  if cardinality(v_selected_ids) <> (
    select count(*)
    from public.teacher_learner as teacher_learner
    where teacher_learner.teacher_account_id = v_teacher_account_id
      and teacher_learner.learner_profile_id = any(v_selected_ids)
  ) then
    raise exception 'learner_profile_not_found' using errcode = 'P0002';
  end if;

  if v_run.id is not null then
    update public.lesson_run as run
    set scheduled_at = p_scheduled_at,
        planned_duration_minutes = v_duration_minutes
    where run.id = v_run.id
    returning run.* into v_run;

    delete from public.learning_record as record
    where record.lesson_run_id = v_run.id
      and record.occurred_at is null;
  else
    insert into public.lesson_run (
      lesson_id,
      scheduled_at,
      planned_duration_minutes
    )
    values (
      p_lesson_id,
      p_scheduled_at,
      v_duration_minutes
    )
    returning * into v_run;
  end if;

  insert into public.learning_record (
    learner_profile_id,
    recorded_by_account_id,
    lesson_run_id,
    source_course_id,
    source_lesson_id
  )
  select
    selected.id,
    v_teacher_account_id,
    v_run.id,
    v_course_id,
    p_lesson_id
  from unnest(v_selected_ids) as selected(id);

  return v_run;
end
$$;


--
-- Name: set_current_account_pin(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_current_account_pin(p_actor_auth_user_id uuid, p_raw_pin text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform public.set_current_account_pin_impl(p_actor_auth_user_id, p_raw_pin);
end
$$;


--
-- Name: set_current_account_pin_impl(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_current_account_pin_impl(p_actor_auth_user_id uuid, p_raw_pin text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_account_id uuid;
  v_pin_hash text;
begin
  if p_actor_auth_user_id is null
    or p_raw_pin is null
    or p_raw_pin !~ '^\d{4,8}$'
  then
    raise exception 'account_pin_invalid' using errcode = '22023';
  end if;

  select account.id into v_account_id
  from public.account as account
  where account.auth_user_id = p_actor_auth_user_id
    and account.status in ('active', 'provisional')
  for update of account;

  if not found then
    raise exception 'account_not_found' using errcode = 'P0002';
  end if;

  v_pin_hash := extensions.crypt(p_raw_pin, extensions.gen_salt('bf'));

  insert into public.account_security as target (
    account_id, pin_hash, pin_created_at, pin_updated_at
  ) values (
    v_account_id, v_pin_hash, now(), now()
  )
  on conflict (account_id) do update
    set pin_hash = excluded.pin_hash,
        pin_failed_attempts = 0,
        pin_locked_until = null,
        pin_created_at = coalesce(target.pin_created_at, now()),
        pin_updated_at = now();

end
$_$;


--
-- Name: set_lesson_component_student_screen(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_lesson_component_student_screen(p_component_id uuid, p_mode text, p_slide_id uuid DEFAULT NULL::uuid) RETURNS TABLE(id uuid, lesson_id uuid, type_key text, schema_version integer, "position" integer, payload jsonb, placement_config jsonb, visibility text, student_slide_id uuid, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_user_id uuid := (select auth.uid());
  v_lesson_id uuid;
  v_component_position integer;
  v_previous_slide_position integer;
  v_next_slide_position integer;
  v_target_slide_position integer;
  v_target_slide_id uuid;
  v_insert_position integer;
begin
  if v_actor_user_id is null then
    raise exception 'component_not_found' using errcode = 'P0002';
  end if;

  if p_mode is null or p_mode not in ('hide', 'existing', 'new') then
    raise exception
      'student_screen_mode_invalid'
      using errcode = '22023';
  end if;

  if (p_mode = 'existing' and p_slide_id is null)
    or (p_mode <> 'existing' and p_slide_id is not null)
  then
    raise exception
      'student_screen_slide_argument_invalid'
      using errcode = '22023';
  end if;

  select component.lesson_id
  into v_lesson_id
  from public.lesson_component as component
  join public.lesson as lesson on lesson.id = component.lesson_id
  join public.course as course on course.id = lesson.course_id
  join public.account as account on account.id = course.owner_account_id
  where component.id = p_component_id
    and account.auth_user_id = v_actor_user_id;

  if not found then
    raise exception 'component_not_found' using errcode = 'P0002';
  end if;

  -- Parent-row serialization gives assignment and reorder one lock order per
  -- Lesson, including when callers target different components.
  perform 1
  from public.lesson as lesson
  join public.course as course on course.id = lesson.course_id
  join public.account as account on account.id = course.owner_account_id
  where lesson.id = v_lesson_id
    and account.auth_user_id = v_actor_user_id
  for update of lesson;

  if not found then
    raise exception 'component_not_found' using errcode = 'P0002';
  end if;

  perform 1
  from public.lesson_component as component
  where component.lesson_id = v_lesson_id
  order by component.id
  for update;

  perform 1
  from public.lesson_student_slide as slide
  where slide.lesson_id = v_lesson_id
  order by slide.id
  for update;

  select component.position
  into v_component_position
  from public.lesson_component as component
  where component.id = p_component_id
    and component.lesson_id = v_lesson_id;

  if not found then
    raise exception 'component_not_found' using errcode = 'P0002';
  end if;

  if p_mode = 'hide' then
    update public.lesson_component as component
    set visibility = 'staff_only',
        student_slide_id = null
    where component.id = p_component_id;
  else
    select slide.position
    into v_previous_slide_position
    from public.lesson_component as component
    join public.lesson_student_slide as slide
      on slide.id = component.student_slide_id
    where component.lesson_id = v_lesson_id
      and component.id <> p_component_id
      and component.visibility = 'learner_visible'
      and component.position < v_component_position
    order by component.position desc
    limit 1;

    select slide.position
    into v_next_slide_position
    from public.lesson_component as component
    join public.lesson_student_slide as slide
      on slide.id = component.student_slide_id
    where component.lesson_id = v_lesson_id
      and component.id <> p_component_id
      and component.visibility = 'learner_visible'
      and component.position > v_component_position
    order by component.position
    limit 1;

    if p_mode = 'existing' then
      select slide.position
      into v_target_slide_position
      from public.lesson_student_slide as slide
      where slide.id = p_slide_id
        and slide.lesson_id = v_lesson_id;

      if not found then
        raise exception
          'student_slide_not_found'
          using errcode = 'P0002';
      end if;

      if (
        v_previous_slide_position is not null
        and v_target_slide_position < v_previous_slide_position
      ) or (
        v_next_slide_position is not null
        and v_target_slide_position > v_next_slide_position
      ) then
        raise exception
          'student_slide_target_out_of_order'
          using errcode = '23514';
      end if;

      v_target_slide_id := p_slide_id;
    else
      if v_previous_slide_position is not null
        and v_next_slide_position is not null
        and v_previous_slide_position = v_next_slide_position
      then
        raise exception
          'student_slide_cannot_split_group'
          using errcode = '23514';
      end if;

      v_insert_position := case
        when v_next_slide_position is not null
          then v_next_slide_position
        when v_previous_slide_position is not null
          then v_previous_slide_position + 1
        else 1
      end;

      update public.lesson_student_slide as slide
      set position = slide.position + 1
      where slide.lesson_id = v_lesson_id
        and slide.position >= v_insert_position;

      insert into public.lesson_student_slide as inserted_slide (
        lesson_id,
        position
      )
      values (v_lesson_id, v_insert_position)
      returning inserted_slide.id into v_target_slide_id;
    end if;

    update public.lesson_component as component
    set visibility = 'learner_visible',
        student_slide_id = v_target_slide_id
    where component.id = p_component_id;
  end if;

  return query
  select
    component.id,
    component.lesson_id,
    component.type_key,
    component.schema_version,
    component.position,
    component.payload,
    component.placement_config,
    component.visibility,
    component.student_slide_id,
    component.created_at,
    component.updated_at
  from public.lesson_component as component
  where component.id = p_component_id;
end
$$;


--
-- Name: set_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  new.updated_at = now();
  return new;
end;
$$;


--
-- Name: start_lesson_run(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.start_lesson_run(p_lesson_run_id uuid, p_started_at timestamp with time zone DEFAULT now()) RETURNS public.lesson_run
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_run public.lesson_run%rowtype;
begin
  if (select auth.uid()) is null or p_started_at is null then
    raise exception 'lesson_run_not_found' using errcode = 'P0002';
  end if;

  select run.* into v_run
  from public.lesson_run as run
  join public.lesson as lesson on lesson.id = run.lesson_id
  join public.course as course on course.id = lesson.course_id
  join public.account as account on account.id = course.owner_account_id
  where run.id = p_lesson_run_id
    and account.auth_user_id = (select auth.uid())
  for update of run;

  if not found then
    raise exception 'lesson_run_not_found' using errcode = 'P0002';
  end if;
  if v_run.cancelled_at is not null or v_run.ended_at is not null then
    raise exception 'lesson_run_not_open' using errcode = '55000';
  end if;

  if v_run.started_at is null or not v_run.started_at_is_actual then
    update public.lesson_run as run
    set started_at = p_started_at,
        started_at_is_actual = true
    where run.id = p_lesson_run_id
    returning run.* into v_run;
  end if;
  return v_run;
end
$$;


--
-- Name: sync_course_audience_type_from_links(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_course_audience_type_from_links() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_course_id uuid;
begin
  for v_course_id in
    select distinct candidate.course_id
    from (
      select case when tg_op <> 'DELETE' then new.course_id end as course_id
      union all
      select case when tg_op <> 'INSERT' then old.course_id end
    ) as candidate
    where candidate.course_id is not null
    order by candidate.course_id
  loop
    update public.course as course
    set audience_type = case
      when exists (
        select 1
        from public.course_learner as course_learner
        where course_learner.course_id = v_course_id
      ) or exists (
        select 1
        from public.course_learner_group as course_group
        where course_group.course_id = v_course_id
      ) then 'learner_profile'
      else 'none'
    end
    where course.id = v_course_id;
  end loop;

  return null;
end
$$;


--
-- Name: sync_provisional_account_from_auth_metadata(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_provisional_account_from_auth_metadata() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_raw_invitation_id text :=
    new.raw_app_meta_data ->> 'activation_invitation_id';
  v_invitation_id uuid;
  v_auth_xmin xid;
  v_updated_count integer;
begin
  if (new.raw_app_meta_data ->> 'identity_status')
      is distinct from 'provisional'
    or coalesce(lower(new.email), '')
      !~ '^[0-9a-f]{64}@learners[.]shidao[.]internal$'
    or coalesce(v_raw_invitation_id, '')
      !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  then
    return new;
  end if;

  v_invitation_id := v_raw_invitation_id::uuid;

  if not exists (
    select 1
    from public.learner_claim_invitation as invitation
    join public.learner_profile as source
      on source.id = invitation.source_learner_profile_id
    where invitation.id = v_invitation_id
      and invitation.kind = 'child_activation'
      and invitation.status in ('pending', 'bound')
      and invitation.expires_at > clock_timestamp()
      and source.account_id is null
  ) then
    return new;
  end if;

  select auth_user.xmin into v_auth_xmin
  from auth.users as auth_user
  where auth_user.id = new.id;

  update public.account as account
  set status = 'provisional'
  where account.auth_user_id = new.id
    and account.status = 'active'
    -- GoTrue's two writes share one transaction ID.  Once Auth creation
    -- commits, the Auth row receives a new xmin on every later UPDATE while
    -- Account.xmin retains its creation transaction.
    and account.xmin = v_auth_xmin
    and account.created_at = account.updated_at
    and (
      select count(*)
      from public.learner_profile as profile
      where profile.account_id = account.id
    ) = 1
    and not exists (
      select 1
      from public.account_login_alias as alias
      where alias.account_id = account.id
    )
    and exists (
      select 1
      from public.account_security as security
      where security.account_id = account.id
        and security.pin_hash is null
        and security.pin_failed_attempts = 0
        and security.pin_locked_until is null
        and security.pin_created_at is null
        and security.pin_updated_at is null
        and security.last_pin_login_at is null
        and security.sessions_invalid_before is null
        and security.created_at = security.updated_at
    )
    and exists (
      select 1
      from public.account_preference as preference
      where preference.account_id = account.id
        and preference.last_selected_school_id is null
        and preference.theme is null
        and preference.settings = '{}'::jsonb
        and preference.created_at = preference.updated_at
    );

  get diagnostics v_updated_count = row_count;

  if v_updated_count = 0
    and exists (
      select 1
      from public.account as account
      where account.auth_user_id = new.id
        and account.status = 'active'
        and account.xmin = v_auth_xmin
    )
  then
    -- A trusted marker in the creation transaction must either consume the
    -- pristine bootstrap or abort the Auth create.  Silently accepting a
    -- partially initialized active Account would strand the activation flow.
    raise exception 'learner_identity_provisional_auth_sync_pristine_mismatch'
      using errcode = '55000';
  end if;

  return new;
end
$_$;


--
-- Name: account; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.account (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    auth_user_id uuid NOT NULL,
    display_name text NOT NULL,
    locale text DEFAULT 'ru'::text NOT NULL,
    timezone text DEFAULT 'Europe/Moscow'::text NOT NULL,
    status text DEFAULT 'active'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT account_display_name_check CHECK ((btrim(display_name) <> ''::text)),
    CONSTRAINT account_status_check CHECK ((status = ANY (ARRAY['active'::text, 'provisional'::text, 'suspended'::text, 'deleted'::text])))
);


--
-- Name: update_current_account_profile(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_current_account_profile(p_display_name text, p_locale text, p_timezone text) RETURNS public.account
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_account public.account%rowtype;
begin
  if (select auth.uid()) is null
    or p_display_name is null
    or btrim(p_display_name) = ''
    or char_length(btrim(p_display_name)) > 160
    or p_locale is null
    or btrim(p_locale) = ''
    or char_length(btrim(p_locale)) > 35
    or p_timezone is null
    or btrim(p_timezone) = ''
    or char_length(btrim(p_timezone)) > 100
  then
    raise exception 'account_profile_invalid' using errcode = '22023';
  end if;

  update public.account as account
  set display_name = btrim(p_display_name),
      locale = btrim(p_locale),
      timezone = btrim(p_timezone)
  where account.auth_user_id = (select auth.uid())
    and account.status = 'active'
  returning account.* into v_account;

  if not found then
    raise exception 'account_not_found' using errcode = 'P0002';
  end if;

  -- Account-owned canonical name follows the Account profile.  Every
  -- teacher-local directory name remains untouched in teacher_learner.
  update public.learner_profile as profile
  set display_name = v_account.display_name
  where profile.account_id = v_account.id;

  return v_account;
end
$$;


--
-- Name: update_learner_group(uuid, text, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_learner_group(p_learner_group_id uuid, p_name text, p_learner_profile_ids uuid[] DEFAULT '{}'::uuid[]) RETURNS public.learner_group
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_user_id uuid := (select auth.uid());
  v_teacher_account_id uuid;
  v_profile_ids uuid[];
  v_group public.learner_group%rowtype;
begin
  if v_actor_user_id is null then
    raise exception 'learner_group_not_found' using errcode = 'P0002';
  end if;

  if p_name is null
    or btrim(p_name) = ''
    or char_length(btrim(p_name)) > 160
  then
    raise exception 'learner_group_name_invalid' using errcode = '22023';
  end if;

  if array_position(p_learner_profile_ids, null) is not null
    or cardinality(coalesce(p_learner_profile_ids, '{}'::uuid[])) > 200
  then
    raise exception 'learner_profile_ids_invalid' using errcode = '22023';
  end if;

  select account.id
  into v_teacher_account_id
  from public.account as account
  where account.auth_user_id = v_actor_user_id
  for update of account;

  if not found then
    raise exception 'learner_group_not_found' using errcode = 'P0002';
  end if;

  perform 1
  from public.course as course
  join public.course_learner_group as course_group
    on course_group.course_id = course.id
  where course_group.learner_group_id = p_learner_group_id
    and course.owner_account_id = v_teacher_account_id
  order by course.id
  for update of course;

  select learner_group.*
  into v_group
  from public.learner_group as learner_group
  where learner_group.id = p_learner_group_id
    and learner_group.owner_account_id = v_teacher_account_id
  for update of learner_group;

  if not found then
    raise exception 'learner_group_not_found' using errcode = 'P0002';
  end if;

  if exists (
    select 1
    from public.learner_group as learner_group
    where learner_group.owner_account_id = v_teacher_account_id
      and learner_group.id <> p_learner_group_id
      and lower(btrim(learner_group.name)) = lower(btrim(p_name))
  ) then
    raise exception 'learner_group_name_taken' using errcode = '23505';
  end if;

  select coalesce(array_agg(requested.id order by requested.id), '{}'::uuid[])
  into v_profile_ids
  from (
    select distinct requested_id as id
    from unnest(coalesce(p_learner_profile_ids, '{}'::uuid[]))
      as requested(requested_id)
  ) as requested;

  perform 1
  from public.teacher_learner as teacher_learner
  where teacher_learner.teacher_account_id = v_teacher_account_id
    and teacher_learner.learner_profile_id = any(v_profile_ids)
    and teacher_learner.archived_at is null
  order by teacher_learner.learner_profile_id
  for update of teacher_learner;

  if cardinality(v_profile_ids) <> (
    select count(*)
    from public.teacher_learner as teacher_learner
    where teacher_learner.teacher_account_id = v_teacher_account_id
      and teacher_learner.learner_profile_id = any(v_profile_ids)
      and teacher_learner.archived_at is null
  ) then
    raise exception 'learner_profile_not_found' using errcode = 'P0002';
  end if;

  if exists (
    select 1
    from public.course_learner_group as target_link
    where target_link.learner_group_id = p_learner_group_id
      and (
        select count(*)
        from (
          select course_learner.learner_profile_id
          from public.course_learner as course_learner
          join public.teacher_learner as teacher_learner
            on teacher_learner.teacher_account_id = v_teacher_account_id
           and teacher_learner.learner_profile_id = course_learner.learner_profile_id
           and teacher_learner.archived_at is null
          where course_learner.course_id = target_link.course_id
          union
          select member.learner_profile_id
          from public.course_learner_group as course_group
          join public.learner_group_member as member
            on member.learner_group_id = course_group.learner_group_id
          join public.teacher_learner as teacher_learner
            on teacher_learner.teacher_account_id = v_teacher_account_id
           and teacher_learner.learner_profile_id = member.learner_profile_id
           and teacher_learner.archived_at is null
          where course_group.course_id = target_link.course_id
            and course_group.learner_group_id <> p_learner_group_id
          union
          select requested.id
          from unnest(v_profile_ids) as requested(id)
        ) as effective
      ) > 200
  ) then
    raise exception 'course_audience_too_large' using errcode = '22023';
  end if;

  update public.learner_group as learner_group
  set name = btrim(p_name)
  where learner_group.id = p_learner_group_id
  returning learner_group.* into v_group;

  delete from public.learner_group_member as member
  where member.learner_group_id = p_learner_group_id
    and not (member.learner_profile_id = any(v_profile_ids));

  insert into public.learner_group_member (
    learner_group_id,
    learner_profile_id
  )
  select p_learner_group_id, requested.id
  from unnest(v_profile_ids) as requested(id)
  on conflict (learner_group_id, learner_profile_id) do nothing;

  return v_group;
end
$$;


--
-- Name: update_learner_profile_with_groups(uuid, text, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_learner_profile_with_groups(p_learner_profile_id uuid, p_display_name text, p_learner_group_ids uuid[] DEFAULT '{}'::uuid[]) RETURNS public.teacher_learner
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_user_id uuid := (select auth.uid());
  v_teacher_account_id uuid;
  v_group_ids uuid[];
  v_relation public.teacher_learner%rowtype;
begin
  if v_actor_user_id is null then
    raise exception 'learner_profile_not_found' using errcode = 'P0002';
  end if;

  if p_display_name is null
    or btrim(p_display_name) = ''
    or char_length(btrim(p_display_name)) > 160
  then
    raise exception 'learner_profile_name_invalid' using errcode = '22023';
  end if;

  if array_position(p_learner_group_ids, null) is not null
    or cardinality(coalesce(p_learner_group_ids, '{}'::uuid[])) > 200
  then
    raise exception 'learner_group_ids_invalid' using errcode = '22023';
  end if;

  select account.id
  into v_teacher_account_id
  from public.account as account
  where account.auth_user_id = v_actor_user_id
  for update of account;

  if not found then
    raise exception 'learner_profile_not_found' using errcode = 'P0002';
  end if;

  if not exists (
    select 1
    from public.teacher_learner as teacher_learner
    where teacher_learner.teacher_account_id = v_teacher_account_id
      and teacher_learner.learner_profile_id = p_learner_profile_id
      and teacher_learner.archived_at is null
  ) then
    raise exception 'learner_profile_not_found' using errcode = 'P0002';
  end if;

  select coalesce(array_agg(requested.id order by requested.id), '{}'::uuid[])
  into v_group_ids
  from (
    select distinct requested_id as id
    from unnest(coalesce(p_learner_group_ids, '{}'::uuid[]))
      as requested(requested_id)
  ) as requested;

  if cardinality(v_group_ids) <> (
    select count(*)
    from public.learner_group as learner_group
    where learner_group.id = any(v_group_ids)
      and learner_group.owner_account_id = v_teacher_account_id
  ) then
    raise exception 'learner_group_not_found' using errcode = 'P0002';
  end if;

  perform 1
  from public.course as course
  join public.course_learner_group as course_group
    on course_group.course_id = course.id
  where course_group.learner_group_id = any(v_group_ids)
    and course.owner_account_id = v_teacher_account_id
  order by course.id
  for update of course;

  if exists (
    select 1
    from (
      select distinct course_group.course_id
      from public.course_learner_group as course_group
      where course_group.learner_group_id = any(v_group_ids)
    ) as target_course
    where not exists (
      select 1
      from (
        select course_learner.learner_profile_id
        from public.course_learner as course_learner
        join public.teacher_learner as teacher_learner
          on teacher_learner.teacher_account_id = v_teacher_account_id
         and teacher_learner.learner_profile_id = course_learner.learner_profile_id
         and teacher_learner.archived_at is null
        where course_learner.course_id = target_course.course_id
        union
        select member.learner_profile_id
        from public.course_learner_group as linked_group
        join public.learner_group_member as member
          on member.learner_group_id = linked_group.learner_group_id
        join public.teacher_learner as teacher_learner
          on teacher_learner.teacher_account_id = v_teacher_account_id
         and teacher_learner.learner_profile_id = member.learner_profile_id
         and teacher_learner.archived_at is null
        where linked_group.course_id = target_course.course_id
      ) as current_effective
      where current_effective.learner_profile_id = p_learner_profile_id
    )
      and (
        select count(*)
        from (
          select course_learner.learner_profile_id
          from public.course_learner as course_learner
          join public.teacher_learner as teacher_learner
            on teacher_learner.teacher_account_id = v_teacher_account_id
           and teacher_learner.learner_profile_id = course_learner.learner_profile_id
           and teacher_learner.archived_at is null
          where course_learner.course_id = target_course.course_id
          union
          select member.learner_profile_id
          from public.course_learner_group as linked_group
          join public.learner_group_member as member
            on member.learner_group_id = linked_group.learner_group_id
          join public.teacher_learner as teacher_learner
            on teacher_learner.teacher_account_id = v_teacher_account_id
           and teacher_learner.learner_profile_id = member.learner_profile_id
           and teacher_learner.archived_at is null
          where linked_group.course_id = target_course.course_id
        ) as effective
      ) >= 200
  ) then
    raise exception 'course_audience_too_large' using errcode = '22023';
  end if;

  perform 1
  from public.learner_group as learner_group
  where learner_group.id = any(v_group_ids)
    and learner_group.owner_account_id = v_teacher_account_id
  order by learner_group.id
  for update of learner_group;

  select teacher_learner.*
  into v_relation
  from public.teacher_learner as teacher_learner
  where teacher_learner.teacher_account_id = v_teacher_account_id
    and teacher_learner.learner_profile_id = p_learner_profile_id
    and teacher_learner.archived_at is null
  for update of teacher_learner;

  if not found then
    raise exception 'learner_profile_not_found' using errcode = 'P0002';
  end if;

  update public.teacher_learner as teacher_learner
  set display_name = btrim(p_display_name)
  where teacher_learner.teacher_account_id = v_teacher_account_id
    and teacher_learner.learner_profile_id = p_learner_profile_id
  returning teacher_learner.* into v_relation;

  delete from public.learner_group_member as member
  using public.learner_group as learner_group
  where learner_group.id = member.learner_group_id
    and learner_group.owner_account_id = v_teacher_account_id
    and member.learner_profile_id = p_learner_profile_id
    and not (member.learner_group_id = any(v_group_ids));

  insert into public.learner_group_member (
    learner_group_id,
    learner_profile_id
  )
  select requested.id, p_learner_profile_id
  from unnest(v_group_ids) as requested(id)
  on conflict (learner_group_id, learner_profile_id) do nothing;

  return v_relation;
end
$$;


--
-- Name: verify_account_pin_credential(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verify_account_pin_credential(p_identifier text, p_raw_pin text) RETURNS TABLE(auth_user_id uuid, auth_email text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_alias public.account_login_alias%rowtype;
  v_account public.account%rowtype;
  v_security public.account_security%rowtype;
begin
  if p_identifier is null or p_raw_pin is null
    or p_raw_pin !~ '^\d{4,8}$'
  then
    return;
  end if;

  select alias.* into v_alias
  from public.account_login_alias as alias
  where alias.normalized_login = lower(btrim(p_identifier))
    and alias.revoked_at is null
  for update of alias;

  if not found then
    return;
  end if;

  select account.* into v_account
  from public.account as account
  where account.id = v_alias.account_id
    and account.status = 'active'
  for update of account;

  if not found then return; end if;

  insert into public.account_security (account_id)
  values (v_account.id)
  on conflict (account_id) do nothing;

  select security.* into v_security
  from public.account_security as security
  where security.account_id = v_account.id
  for update of security;

  if v_security.pin_locked_until is not null
    and v_security.pin_locked_until > now()
  then
    return;
  end if;

  if v_security.pin_hash is not null
    and extensions.crypt(p_raw_pin, v_security.pin_hash) = v_security.pin_hash
  then
    update public.account_security
    set pin_failed_attempts = 0,
        pin_locked_until = null,
        last_pin_login_at = now()
    where account_id = v_account.id;

    return query
      select v_account.auth_user_id, auth_user.email::text
      from auth.users as auth_user
      where auth_user.id = v_account.auth_user_id;
    return;
  end if;

  update public.account_security
  set pin_failed_attempts = least(pin_failed_attempts + 1, 100),
      pin_locked_until = case
        when pin_failed_attempts + 1 >= 5 then now() + interval '15 minutes'
        else null
      end
  where account_id = v_account.id;
end
$_$;


--
-- Name: verify_current_account_pin(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verify_current_account_pin(p_raw_pin text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_account_id uuid;
  v_security public.account_security%rowtype;
begin
  if (select auth.uid()) is null
    or p_raw_pin is null
    or p_raw_pin !~ '^\d{4,8}$'
  then
    return false;
  end if;

  select account.id into v_account_id
  from public.account as account
  where account.auth_user_id = (select auth.uid())
    and account.status = 'active'
  for update of account;

  if not found then return false; end if;

  select security.* into v_security
  from public.account_security as security
  where security.account_id = v_account_id
  for update of security;

  if not found
    or v_security.pin_hash is null
    or (v_security.pin_locked_until is not null and v_security.pin_locked_until > now())
  then
    return false;
  end if;

  if extensions.crypt(p_raw_pin, v_security.pin_hash) = v_security.pin_hash then
    update public.account_security
    set pin_failed_attempts = 0,
        pin_locked_until = null,
        last_pin_login_at = now()
    where account_id = v_account_id;
    return true;
  end if;

  update public.account_security
  set pin_failed_attempts = least(pin_failed_attempts + 1, 100),
      pin_locked_until = case
        when pin_failed_attempts + 1 >= 5 then now() + interval '15 minutes'
        else null
      end
  where account_id = v_account_id;
  return false;
end
$_$;


