    CONSTRAINT learner_connection_request_expiry_check CHECK ((expires_at > created_at)),
    CONSTRAINT learner_connection_request_local_name_check CHECK (((btrim(local_display_name) <> ''::text) AND (char_length(local_display_name) <= 160))),
    CONSTRAINT learner_connection_request_method_check CHECK ((method = ANY (ARRAY['share_code'::text, 'email'::text, 'exact_handle'::text]))),
    CONSTRAINT learner_connection_request_method_shape_check CHECK ((((method = 'share_code'::text) AND (share_code_id IS NOT NULL) AND (recipient_email_digest IS NULL) AND (token_digest IS NULL) AND (learner_profile_id IS NOT NULL)) OR ((method = 'email'::text) AND (share_code_id IS NULL) AND (recipient_email_digest IS NOT NULL) AND ((status <> 'pending'::text) OR (token_digest IS NOT NULL))) OR ((method = 'exact_handle'::text) AND (share_code_id IS NULL) AND (recipient_email_digest IS NULL) AND (token_digest IS NULL) AND (learner_profile_id IS NOT NULL)))),
    CONSTRAINT learner_connection_request_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'accepted'::text, 'rejected'::text, 'cancelled'::text, 'expired'::text]))),
    CONSTRAINT learner_connection_request_token_digest_check CHECK (((token_digest IS NULL) OR (octet_length(token_digest) = 32)))
);


