-- Name: learner_profile_merge; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.learner_profile_merge (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    source_learner_profile_id uuid NOT NULL,
    target_learner_profile_id uuid NOT NULL,
    invitation_id uuid,
    requested_by_account_id uuid NOT NULL,
    subject_account_id uuid NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    preview_fingerprint bytea,
    preview_payload jsonb,
    expires_at timestamp with time zone NOT NULL,
    completed_at timestamp with time zone,
    cancelled_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT learner_profile_merge_distinct_profiles_check CHECK ((source_learner_profile_id <> target_learner_profile_id)),
    CONSTRAINT learner_profile_merge_expiry_check CHECK ((expires_at > created_at)),
    CONSTRAINT learner_profile_merge_fingerprint_check CHECK (((preview_fingerprint IS NULL) OR (octet_length(preview_fingerprint) = 32))),
    CONSTRAINT learner_profile_merge_payload_check CHECK (((preview_payload IS NULL) OR (jsonb_typeof(preview_payload) = 'object'::text))),
    CONSTRAINT learner_profile_merge_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'ready'::text, 'completed'::text, 'cancelled'::text, 'failed'::text])))
);


--
-- Name: learner_profile_merge_conflict; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.learner_profile_merge_conflict (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    merge_operation_id uuid NOT NULL,
    lesson_run_id uuid NOT NULL,
    primary_record_id uuid NOT NULL,
    superseded_record_id uuid NOT NULL,
    resolution text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT learner_profile_merge_conflict_records_check CHECK ((primary_record_id <> superseded_record_id)),
    CONSTRAINT learner_profile_merge_conflict_resolution_check CHECK ((resolution = ANY (ARRAY['keep_target_primary'::text, 'keep_source_primary'::text])))
);


--
-- Name: learner_profile_merge_private_detail; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.learner_profile_merge_private_detail (
    merge_operation_id uuid NOT NULL,
    teacher_account_id uuid NOT NULL,
    discarded_source_display_name text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT learner_profile_merge_private_name_check CHECK (((btrim(discarded_source_display_name) <> ''::text) AND (char_length(discarded_source_display_name) <= 160)))
);


--
-- Name: learner_profile_share_code; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.learner_profile_share_code (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    learner_profile_id uuid NOT NULL,
    code_digest bytea NOT NULL,
    status text DEFAULT 'active'::text NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    used_at timestamp with time zone,
    revoked_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT learner_profile_share_code_digest_check CHECK ((octet_length(code_digest) = 32)),
    CONSTRAINT learner_profile_share_code_expiry_check CHECK ((expires_at > created_at)),
    CONSTRAINT learner_profile_share_code_state_check CHECK ((((status = 'active'::text) AND (used_at IS NULL) AND (revoked_at IS NULL)) OR ((status = 'used'::text) AND (used_at IS NOT NULL) AND (revoked_at IS NULL)) OR ((status = 'revoked'::text) AND (revoked_at IS NOT NULL)) OR (status = 'expired'::text))),
    CONSTRAINT learner_profile_share_code_status_check CHECK ((status = ANY (ARRAY['active'::text, 'used'::text, 'revoked'::text, 'expired'::text])))
);


--
-- Name: learning_record; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.learning_record (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    learner_profile_id uuid NOT NULL,
    lesson_run_id uuid,
    source_course_id uuid,
    source_lesson_id uuid,
    occurred_at timestamp with time zone,
    was_present boolean,
    needs_repeat boolean,
    teacher_comment text,
    course_title_at_time text,
    lesson_title_at_time text,
    subject_at_time text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    recorded_by_account_id uuid NOT NULL,
    shared_with_learner_at timestamp with time zone,
    actual_duration_minutes_at_time integer,
    superseded_by_record_id uuid,
    CONSTRAINT learning_record_actual_duration_check CHECK (((actual_duration_minutes_at_time IS NULL) OR ((occurred_at IS NOT NULL) AND ((actual_duration_minutes_at_time >= 1) AND (actual_duration_minutes_at_time <= 720))))),
    CONSTRAINT learning_record_draft_or_final_check CHECK ((((occurred_at IS NULL) AND (lesson_run_id IS NOT NULL) AND (was_present IS NULL) AND (needs_repeat IS NULL) AND (teacher_comment IS NULL) AND (course_title_at_time IS NULL) AND (lesson_title_at_time IS NULL) AND (subject_at_time IS NULL)) OR ((occurred_at IS NOT NULL) AND (was_present IS NOT NULL) AND (course_title_at_time IS NOT NULL) AND (btrim(course_title_at_time) <> ''::text) AND (lesson_title_at_time IS NOT NULL) AND (btrim(lesson_title_at_time) <> ''::text)))),
    CONSTRAINT learning_record_not_self_superseded_check CHECK (((superseded_by_record_id IS NULL) OR (superseded_by_record_id <> id))),
    CONSTRAINT learning_record_repeat_requires_presence_check CHECK (((needs_repeat IS NOT TRUE) OR (was_present IS TRUE))),
    CONSTRAINT learning_record_shared_comment_shape_check CHECK (((shared_with_learner_at IS NULL) OR ((occurred_at IS NOT NULL) AND (teacher_comment IS NOT NULL) AND (btrim(teacher_comment) <> ''::text)))),
    CONSTRAINT learning_record_teacher_comment_check CHECK (((teacher_comment IS NULL) OR ((btrim(teacher_comment) <> ''::text) AND (char_length(teacher_comment) <= 2000))))
);


--
-- Name: lesson; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.lesson (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    course_id uuid NOT NULL,
    "position" integer NOT NULL,
    title text NOT NULL,
    summary text,
    estimated_duration_minutes integer,
    settings jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT lesson_estimated_duration_minutes_check CHECK (((estimated_duration_minutes IS NULL) OR (estimated_duration_minutes > 0))),
    CONSTRAINT lesson_position_check CHECK (("position" > 0)),
    CONSTRAINT lesson_settings_check CHECK ((jsonb_typeof(settings) = 'object'::text)),
    CONSTRAINT lesson_title_check CHECK ((btrim(title) <> ''::text))
);


--
-- Name: lesson_component; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.lesson_component (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    lesson_id uuid NOT NULL,
    "position" integer NOT NULL,
    type_key text NOT NULL,
    schema_version integer DEFAULT 1 NOT NULL,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    placement_config jsonb DEFAULT '{}'::jsonb NOT NULL,
    visibility text DEFAULT 'staff_only'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    student_slide_id uuid,
    CONSTRAINT lesson_component_payload_check CHECK ((jsonb_typeof(payload) = 'object'::text)),
    CONSTRAINT lesson_component_placement_config_check CHECK ((jsonb_typeof(placement_config) = 'object'::text)),
    CONSTRAINT lesson_component_position_check CHECK (("position" > 0)),
    CONSTRAINT lesson_component_schema_version_check CHECK ((schema_version > 0)),
    CONSTRAINT lesson_component_student_screen_assignment_check CHECK ((((visibility = 'staff_only'::text) AND (student_slide_id IS NULL)) OR ((visibility = 'learner_visible'::text) AND (student_slide_id IS NOT NULL)))),
    CONSTRAINT lesson_component_type_key_check CHECK ((btrim(type_key) <> ''::text)),
    CONSTRAINT lesson_component_visibility_check CHECK ((visibility = ANY (ARRAY['staff_only'::text, 'learner_visible'::text])))
);


--
-- Name: lesson_student_slide; Type: TABLE; Schema: public; Owner: -
