    plan_code text DEFAULT 'demo'::text NOT NULL,
    subscription_status text DEFAULT 'active'::text NOT NULL,
    CONSTRAINT school_kind_check CHECK ((kind = ANY (ARRAY['personal'::text, 'organization'::text]))),
